-- ADOPT_ONLY_THE_EXACT_SHAPE: an agent_credentials that already exists must carry exactly the columns and the primary key and check constraints this file defines.
-- Anything else is unknown provenance: fail loudly and change nothing.
DO $$
DECLARE actual text; expected text;
BEGIN
  SELECT string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull::text, ',' ORDER BY a.attname COLLATE "C") INTO actual
    FROM pg_attribute a WHERE a.attrelid = 'public.agent_credentials'::regclass AND a.attnum > 0 AND NOT a.attisdropped;
  expected := 'confirmed_at:timestamp with time zone:false,created_from:text:true,expires_at:timestamp with time zone:true,id:uuid:true,issued_at:timestamp with time zone:true,pending_expires_at:timestamp with time zone:false,predecessor_id:uuid:false,renew_until:timestamp with time zone:true,revoked_at:timestamp with time zone:false,revoked_by:text:false,revoked_reason:text:false,token_hash:text:true,user_id:text:true';
  IF actual IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'agent_credentials exists with an unexpected shape; refusing to adopt it: %', actual;
  END IF;
  IF (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.agent_credentials'::regclass
        AND conname IN ('agent_credentials_pkey', 'agent_credentials_created_from_canonical', 'agent_credentials_renew_after_expiry')) <> 3 THEN
    RAISE EXCEPTION 'agent_credentials exists without its primary key or check constraints; refusing to adopt it';
  END IF;
END $$;
